INSERT INTO public.listing_sources (listing_id, source_type, publisher_name, source_url, reference_code, captured_at, notes) VALUES (property_listing_id, 'editorial_import', 'บริษัท บริหารสินทรัพย์สุขุมวิท จำกัด (SAM)', 'https://www.sam.or.th/site/npa/detail.php?id=22900&keyref=6007684', 'SL0184', now(), 'Official source captured 2026-09-11. Direct sale THB 7,634,000; 16 sq.wah; three bedrooms/four bathrooms; three storeys plus surveyed mezzanine and roof terrace. Address 34 differs from registered acquisition with no number stated; disclosed. Approved-subdivision road. Fourteen source images, latest building photos 2026-03-04. Map filename contains alternate reference 3A0931; both codes and deed/nearby coordinates checked for duplicates with no matches. Coordinates extracted from navigation and cross-checked against map.') ;
